import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)[0])
            candidates.append((fid, t_stat))

    candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated features)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Prefer the one with higher t-statistic as parent
                t1 = None
                t2 = None
                for fid, t in candidates:
                    if fid == fid1:
                        t1 = t
                    elif fid == fid2:
                        t2 = t
                if t1 is not None and t2 is not None:
                    if t1 >= t2:
                        correlated_pairs.add(fid2)
                    else:
                        correlated_pairs.add(fid1)

    # Select top drivers, excluding correlated children
    drivers = []
    for fid, _ in candidates:
        if fid not in correlated_pairs and len(drivers) < MAX_DRIVERS:
            drivers.append(fid)

    # For regression, use all non-derived features
    columns = [fid for fid in feats.ids if feats.types[feats.column(fid)] != 'derived']

    # Look for product terms between top drivers
    products = []
    for i, d1 in enumerate(drivers):
        for j, d2 in enumerate(drivers[i+1:], i+1):
            products.append((d1, d2))

    # Create weighted score from top features
    loadings = {}
    for i, (fid, _) in enumerate(candidates[:len(columns)]):
        loadings[fid] = 1.0 / (i + 1)  # inverse rank weighting

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)
